  1	#!/usr/bin/env node
  2	
  3	/**
  4	 * scripts/cli.js
  5	 *
  6	 * Unified workspace CLI -- interactive command center and direct CLI entry point.
  7	 *
  8	 * Usage:
  9	 *   node scripts/cli.js                     Interactive main menu
 10	 *   node scripts/cli.js help                Show all commands
 11	 *   node scripts/cli.js setup               Interactive setup wizard
 12	 *   node scripts/cli.js setup --all         Non-interactive full setup
 13	 *   node scripts/cli.js setup --components  Run selected components
 14	 *   node scripts/cli.js --skip-setup-check  Skip first-run detection (for CI/automated use)
 15	 *   node scripts/cli.js <command> [flags]   Run a command directly
 16	 */
 17	
 18	import {
 19	  createMenu,
 20	  C,
 21	  log,
 22	  IS_WIN,
 23	  NPM,
 24	  sh,
 25	  runScript,
 26	  runLongScript,
 27	  checkNodeVersion,
 28	  PreflightError,
 29	  waitForKey,
 30	} from '@mistralys/cli-menu';
 31	
 32	import {
 33	  readChangelogVersion,
 34	  readPackageVersion,
 35	  readPyprojectVersion,
 36	} from '@mistralys/cli-menu/changelog';
 37	
 38	import path from 'path';
 39	import fs from 'fs';
 40	import readline from 'readline';
 41	import { spawnSync } from 'child_process';
 42	import { getPublishLocations } from './publish-locations.js';
 43	import { install as mcpGlobalInstall, dryRun as mcpGlobalDryRun, shimConfigExists } from './install-mcp-global.js';
 44	import { HEALTH_CHECKS, runChecks } from './lib/health-checks.js';
 45	
 46	// --- Constants ---
 47	
 48	const WORKSPACE_ROOT   = path.resolve(import.meta.dirname, '..');
 49	const SCRIPTS_DIR      = import.meta.dirname;
 50	const MCP_SERVER_DIR   = path.join(WORKSPACE_ROOT, 'mcp-server');
 51	const PERSONAS_DIR     = path.join(WORKSPACE_ROOT, 'personas');
 52	const ORCHESTRATOR_DIR = path.join(WORKSPACE_ROOT, 'orchestrator');
 53	const CHANGELOG_FILE   = path.join(WORKSPACE_ROOT, 'changelog.md');
 54	// --- Pre-flight checks ---
 55	
 56	function checkWorkspaceRoot() {
 57	  if (!fs.existsSync(MCP_SERVER_DIR)) {
 58	    throw new PreflightError('Run from the workspace root (mcp-server/ not found)');
 59	  }
 60	}
 61	
 62	// --- Python finder (for orchestrator setup) ---
 63	
 64	function findPython() {
 65	  const candidates = IS_WIN ? ['python', 'python3', 'py'] : ['python3', 'python'];
 66	  for (const cand of candidates) {
 67	    const a = cand === 'py' ? ['-3', '--version'] : ['--version'];
 68	    const r = spawnSync(cand, a, { encoding: 'utf8', shell: false });
 69	    if (r.status !== 0) continue;
 70	    const raw = (r.stdout || '') + (r.stderr || '');
 71	    const m = raw.match(/Python (\d+)\.(\d+)/);
 72	    if (!m) continue;
 73	    if (parseInt(m[1], 10) === 3 && parseInt(m[2], 10) >= 11) return cand;
 74	  }
 75	  return null;
 76	}
 77	
 78	function syncOrchestratorVersion() {
 79	  const changelogPath = path.join(ORCHESTRATOR_DIR, 'changelog.md');
 80	  const pyprojectPath = path.join(ORCHESTRATOR_DIR, 'pyproject.toml');
 81	
 82	  if (!fs.existsSync(changelogPath)) {
 83	    log('  ✗ orchestrator/changelog.md not found');
 84	    return;
 85	  }
 86	  if (!fs.existsSync(pyprojectPath)) {
 87	    log('  ✗ orchestrator/pyproject.toml not found');
 88	    return;
 89	  }
 90	
 91	  try {
 92	    const changelog = fs.readFileSync(changelogPath, 'utf8');
 93	    const versionMatch = changelog.match(/^##\s+(?:\[|v)?(\d+\.\d+\.\d+)/m);
 94	
 95	    if (!versionMatch) {
 96	      log('  ⚠ Could not find version in orchestrator/changelog.md');
 97	      return;
 98	    }
 99	
100	    const newVersion = versionMatch[1];

101	  };
102	
103	  for (let i = 0; i < argv.length; i++) {
104	    const a = argv[i];
105	
106	    // ── Boolean flags ──
107	    if (a === '--help' || a === '-h') { opts.help = true; continue; }
108	    if (a === '--force')              { opts.force = true; continue; }
109	    if (a === '--dry-run')            { opts.dryRun = true; continue; }
110	
111	    // ── Positional argument (non-flag token) ──
112	    if (!a.startsWith('-')) {
113	      if (opts.target === null) {
114	        opts.target = a;
115	        opts.isDir  = null; // auto-detect via statSync
116	      }
117	      continue;
118	    }
119	
120	    // ── Value flags — support both --flag val and --flag=val ──
121	    const eq  = a.indexOf('=');
122	    const key = eq === -1 ? a         : a.slice(0, eq);
123	    const val = eq === -1 ? argv[++i] : a.slice(eq + 1);
124	
125	    if (key === '--file') {
126	      opts.target = val;
127	      opts.isDir  = false;
128	      continue;
129	    }
130	    if (key === '--dir') {
131	      opts.target = val;
132	      opts.isDir  = true;
133	      continue;
134	    }
135	
136	    // Unknown flag with no '=' — we consumed argv[++i] as val above; undo.
137	    if (eq === -1) i--;
138	  }
139	
140	  return opts;
141	}
142	
143	// ─── File discovery ───────────────────────────────────────────────────────────
144	
145	/**
146	 * Returns the list of `.jsonl` files to process for a given target path.
147	 *
148	 * - If target is a `.jsonl` file: returns `[target]`.
149	 * - If target is a directory: returns all `*.jsonl` files in that directory
150	 *   (non-recursive), sorted alphabetically.
151	 *
152	 * Resolves paths relative to `WORKSPACE_ROOT`.
153	 *
154	 * @param {string} target  Path to a .jsonl file or a directory.
155	 * @param {boolean|null} isDir  If true, treat as directory; if false, treat as file;
156	 *                              if null, auto-detect via fs.statSync.
157	 * @returns {string[]}  Absolute paths to .jsonl files.
158	 */
159	function discoverChunkFiles(target, isDir) {
160	  const resolved = path.isAbsolute(target)
161	    ? target
162	    : path.resolve(WORKSPACE_ROOT, target);
163	
164	  // Auto-detect when isDir is null.
165	  let treatAsDir = isDir;
166	  if (treatAsDir === null) {
167	    try {
168	      const stat = fs.statSync(resolved);
169	      treatAsDir = stat.isDirectory();
170	    } catch {
171	      // Let the caller handle the missing-path error.
172	      return [resolved];
173	    }
174	  }
175	
176	  if (!treatAsDir) {
177	    return [resolved];
178	  }
179	
180	  // Directory mode: collect all *.jsonl files (non-recursive, sorted).
181	  try {
182	    const entries = fs.readdirSync(resolved);
183	    return entries
184	      .filter((f) => f.endsWith('.jsonl'))
185	      .sort()
186	      .map((f) => path.join(resolved, f));
187	  } catch {
188	    return [];
189	  }
190	}
191	
192	// ─── JSONL parser ─────────────────────────────────────────────────────────────
193	
194	/**
195	 * Reads a `.jsonl` chunk file and returns its parsed data lines.
196	 *
197	 * Skips:
198	 *   - Empty/blank lines
199	 *   - The `chunk_format` header line (first line with key `chunk_format`)
200	 *   - Malformed lines that cannot be parsed as JSON
201	 *
202	 * @param {string} filePath  Absolute path to the .jsonl file.
203	 * @returns {object[]}  Array of parsed chunk objects (with `ns` and `msg` fields).
204	 */
205	function parseJsonl(filePath) {
206	  const content = fs.readFileSync(filePath, 'utf8');
207	  const rawLines = content.split('\n');
208	  const nonEmpty = rawLines.map((l) => l.trim()).filter(Boolean);
209	
210	  if (nonEmpty.length === 0) return [];
211	
212	  // Skip the header line (first line with `chunk_format` key).
213	  const firstLine = nonEmpty[0];
214	  let dataLines;
215	  try {
216	    const firstParsed = JSON.parse(firstLine);
217	    if (firstParsed && typeof firstParsed === 'object' && 'chunk_format' in firstParsed) {
218	      dataLines = nonEmpty.slice(1);
219	    } else {
220	      dataLines = nonEmpty;
221	    }
222	  } catch {
223	    dataLines = nonEmpty;
224	  }
225	
226	  const entries = [];
227	  for (const line of dataLines) {
228	    try {
229	      const parsed = JSON.parse(line);
230	
231	      // Normalise object shape: { ns, msg } and array shape: [ns, msg, metadata].
232	      if (Array.isArray(parsed) && parsed.length >= 2) {
233	        entries.push({ ns: parsed[0], msg: parsed[1] });
234	      } else if (parsed && typeof parsed === 'object' && 'ns' in parsed && 'msg' in parsed) {
235	        entries.push({ ns: parsed.ns, msg: parsed.msg });
236	      }
237	      // Lines that don't match either shape are silently skipped.
238	    } catch {
239	      // Malformed JSON — skip silently.
240	    }
241	  }
242	
243	  return entries;
244	}
