248	/**
249	 * Extracts plain text content from a content value.
250	 *
251	 * Handles:
252	 *   - string content (returned as-is)
253	 *   - array of content blocks (joins `text`-type blocks)
254	 *
255	 * @param {string|Array|null|undefined} content
256	 * @returns {string}
257	 */
258	function extractContent(content) {
259	  if (!content) return '';
260	  if (typeof content === 'string') return content;
261	  if (!Array.isArray(content)) return '';
