263	  const parts = [];
264	  for (const block of content) {
265	    if (typeof block === 'string') {
266	      parts.push(block);
267	    } else if (block && typeof block === 'object' && block.type === 'text' && typeof block.text === 'string') {
268	      parts.push(block.text);
269	    }
270	    // Skip tool_use, input_json_delta, and other non-text block types.
271	  }
272	  return parts.join('');
273	}
