330	/**
331	 * Extracts prose text from a single `.jsonl` chunk file and writes a `.md` file
332	 * alongside it (same directory, same base name, `.jsonl` → `.md`).
333	 *
334	 * Behaviour:
335	 *   - Skips write if the `.md` already exists and `opts.force` is false.
336	 *   - With `opts.dryRun`, prints the output path without writing.
337	 *   - Single-namespace output: flat prose (no section headers).
338	 *   - Dual-namespace output: `## Outer Agent` / `## Inner Agent` headers.
339	 *
340	 * @param {string} chunkPath  Absolute path to the source `.jsonl` file.
341	 * @param {{ force: boolean, dryRun: boolean }} opts
342	 * @returns {{ status: 'written'|'skipped'|'dry-run'|'empty', mdPath: string }}
343	 */
344	function extractFile(chunkPath, opts) {
345	  // Derive the output path from the validated source path (server-side derivation
346	  // only — never from user-controlled filenames in the API case).
347	  const ext    = path.extname(chunkPath);          // '.jsonl'
348	  const base   = path.basename(chunkPath, ext);    // e.g. 'run-001'
349	  const dir    = path.dirname(chunkPath);
350	  const mdPath = path.join(dir, base + '.md');
351	
352	  // Dry-run: print path and exit early.
353	  if (opts.dryRun) {
354	    console.log(C.cyan(mdPath));
355	    return { status: 'dry-run', mdPath };
356	  }
357	
358	  // Skip if the .md already exists and --force was not passed.
359	  if (!opts.force && fs.existsSync(mdPath)) {
360	    console.log(C.dim(`  skip  ${mdPath} (already exists; use --force to overwrite)`));
361	    return { status: 'skipped', mdPath };
362	  }
363	
364	  // Parse and assemble.
365	  const entries          = parseJsonl(chunkPath);
366	  const { outer, inner } = assembleText(entries);
367	  const hasOuter         = outer.length > 0;
368	  const hasInner         = inner.length > 0;
369	  const hasDual          = hasOuter && hasInner;  // both namespaces have content
370	  const hasContent       = hasOuter || hasInner;
371	
372	  let mdContent;
373	  if (!hasContent) {
374	    mdContent = '*No dialogue recorded.*\n';
375	  } else if (hasDual) {
376	    // Both outer and inner namespaces have prose — emit section headers.
377	    const parts = [
378	      '## Outer Agent',
379	      '',
380	      outer,
381	      '',
382	      '## Inner Agent',
383	      '',
384	      inner,
385	    ];
386	    mdContent = parts.join('\n') + '\n';
387	  } else {
388	    // Single-namespace: flat prose (whichever namespace has content).
389	    mdContent = (hasOuter ? outer : inner) + '\n';
390	  }
391	
392	  fs.writeFileSync(mdPath, mdContent, 'utf8');
393	  console.log(C.green(`  write ${mdPath}`));
394	  return { status: hasContent ? 'written' : 'empty', mdPath };
395	}
